pub fn readLines(io: std.Io, path: []const u8) ![]const []const u8 {
    const value = try std.Io.Dir.cwd().readFileAlloc(io, path, allocator, .unlimited);
    const lines = split(value, '\n');
    return lines[0 .. lines.len - 1];
}
pub const Point = struct { x: i64, y: i64 };
pub const offsets = [_]i64{ -1, 0, 1 };
pub const Image = struct {
    width: usize,
    height: usize,
    data: []i64,
    pub fn init(width: usize, height: usize) Image {
        const data = alloc(i64, width * height);
        @memset(data, 0);
        return .{ .width = width, .height = height, .data = data };
    }
    pub fn inside(self: Image, point: Point) bool {
        return point.x >= 0 and point.x < n(self.width) and point.y >= 0 and point.y < n(self.height);
    }
    pub fn at(self: Image, point: Point) i64 {
        return self.data[u(point.y) * self.width + u(point.x)];
    }
    pub fn set(self: Image, point: Point, value: i64) void {
        self.data[u(point.y) * self.width + u(point.x)] = value;
    }
fn value(line: []const u8) i64 {
    return number(words(line)[1]);
}
pub fn load(io: std.Io) !Input {
    const lines = try readLines(io, "input/image.pgm");
    const dimensions = words(lines[1]);
    const image = Image.init(u(number(dimensions[0])), u(number(dimensions[1])));
    for (lines[3..], 0..) |line, y| for (words(line), 0..) |field, x| {
        image.data[y * image.width + x] = number(field);
    };
    var trig: Trig = undefined;
    for (try readLines(io, "input/trig.txt"), 0..) |line, t| {
        const fields = words(line);
        trig[t] = .{ number(fields[1]), number(fields[2]) };
    }
    const settings = try readLines(io, "input/params.txt");
    const coefficients = words(settings[1]);
    const kernel = alloc(i64, coefficients.len - 1);
    for (coefficients[1..], kernel) |field, *coefficient| coefficient.* = number(field);
    return .{ .image = image, .trig = trig, .params = .{ .ks = value(settings[0]), .kernel = kernel,
         .divisor = value(settings[2]), .low = value(settings[3]), .high = value(settings[4]), .r_min = value(settings[5]),
         .r_max = value(settings[6]), .circle_percent = value(settings[7]), .circle_count = value(settings[8]),
         .rho_step = value(settings[9]), .vote_threshold = value(settings[10]), .line_count = value(settings[11]),
         .tolerance = value(settings[12]), .max_gap = value(settings[13]), .min_length = value(settings[14]),
         .junction_distance = value(settings[15]), .junction_angle = value(settings[16]), .angle_tolerance = value(settings[17]),
         .square_tolerance = value(settings[18]), .margin = value(settings[19]), .harris_window = value(settings[20]),
         .harris_threshold = value(settings[21]), .corner_count = value(settings[22]), .match_distance = value(settings[23]),
         .overlay_divisor = value(settings[24]) } };
}
pub fn writePgm(io: std.Io, name: []const u8, image: Image) !void {
    var out: Text = .{};
    out.add("P2\n{d} {d}\n255\n", .{ image.width, image.height });
    for (0..image.height) |y| {
        for (0..image.width) |x| out.add("{s}{d}", .{ if (x == 0) "" else " ", image.data[y * image.width + x] });
        out.add("\n", .{});
    }
    try std.Io.Dir.cwd().writeFile(io, .{ .sub_path = fmt("output/{s}", .{name}), .data = out.value() });
}
pub fn absolute(value: i64) i64 {
    return if (value < 0) -value else value;
}
pub fn clamped(image: c.Image, x: i64, y: i64) i64 {
    return image.at(.{ .x = @max(0, @min(c.n(image.width) - 1, x)), .y = @max(0, @min(c.n(image.height) - 1, y)) });
}
pub fn smooth(image: c.Image, p: c.Params) c.Image {
    const out = c.Image.init(image.width, image.height);
    const half = @divTrunc(p.ks - 1, 2);
    for (0..image.height) |yy| for (0..image.width) |xx| {
        const x = c.n(xx);
        const y = c.n(yy);
        var sum: i64 = 0;
        for (0..c.u(p.ks)) |j| for (0..c.u(p.ks)) |i| {
            sum += p.kernel[j * c.u(p.ks) + i] * clamped(image, x + c.n(i) - half, y + c.n(j) - half);
        };
        out.set(.{ .x = x, .y = y }, @divFloor(sum, p.divisor));
    };
    return out;
}
pub const Gradient = struct { gx: c.Image, gy: c.Image, magnitude: c.Image };
pub fn gradient(image: c.Image) Gradient {
    const out: Gradient = .{ .gx = c.Image.init(image.width, image.height), .gy = c.Image.init(image.width,
         image.height), .magnitude = c.Image.init(image.width, image.height) };
    for (0..image.height) |yy| for (0..image.width) |xx| {
        const x = c.n(xx);
        const y = c.n(yy);
        var q: [9]i64 = undefined;
        for (c.offsets, 0..) |dy, j| for (c.offsets, 0..) |dx, i| {
            q[j * 3 + i] = clamped(image, x + dx, y + dy);
        };
        const gx = q[2] + 2 * q[5] + q[8] - q[0] - 2 * q[3] - q[6];
        const gy = q[6] + 2 * q[7] + q[8] - q[0] - 2 * q[1] - q[2];
        const point: c.Point = .{ .x = x, .y = y };
        out.gx.set(point, gx);
        out.gy.set(point, gy);
        out.magnitude.set(point, absolute(gx) + absolute(gy));
    };
    return out;
}
pub const Result = struct { direction: c.Image, nms: c.Image, edges: c.Image, components: []const []const c.Point,
     strong: i64 = 0, weak: i64 = 0 };
pub fn detect(g: filters.Gradient, p: c.Params) Result {
    const width = g.gx.width;
    const height = g.gx.height;
    var out: Result = .{ .direction = c.Image.init(width, height), .nms = c.Image.init(width, height),
         .edges = c.Image.init(width, height), .components = &.{} };
    for (0..height) |yy| for (0..width) |xx| {
        const x = c.n(xx);
        const y = c.n(yy);
        const point: c.Point = .{ .x = x, .y = y };
        const gx = g.gx.at(point);
        const gy = g.gy.at(point);
        const ax = filters.absolute(gx);
        const ay = filters.absolute(gy);
        const direction: i64 = if (29 * ay <= 12 * ax) 0 else if (29 * ay >= 70 * ax) 90 else if (gx * gy < 0) 45 else 135;
        out.direction.set(point, direction);
        if (xx == 0 or yy == 0 or xx == width - 1 or yy == height - 1) continue;
        const previous: c.Point = switch (direction) {
            0 => .{ .x = x - 1, .y = y },
            45 => .{ .x = x + 1, .y = y - 1 },
            90 => .{ .x = x, .y = y - 1 },
            else => .{ .x = x - 1, .y = y - 1 },
        };
        const next: c.Point = switch (direction) {
            0 => .{ .x = x + 1, .y = y },
            45 => .{ .x = x - 1, .y = y + 1 },
            90 => .{ .x = x, .y = y + 1 },
            else => .{ .x = x + 1, .y = y + 1 },
        };
        const value = g.magnitude.at(point);
        if (value > g.magnitude.at(previous) and value >= g.magnitude.at(next)) out.nms.set(point, value);
    };
    var queue: std.ArrayList(c.Point) = .empty;
    for (0..height) |yy| for (0..width) |xx| {
        const point: c.Point = .{ .x = c.n(xx), .y = c.n(yy) };
        const value = out.nms.at(point);
        if (value >= p.high) {
            out.strong += 1;
            out.edges.set(point, 1);
            c.append(c.Point, &queue, point);
        } else if (value >= p.low) out.weak += 1;
    };
    var head: usize = 0;
    while (head < queue.items.len) : (head += 1) {
        const point = queue.items[head];
        for (c.offsets) |dy| for (c.offsets) |dx| {
            const next: c.Point = .{ .x = point.x + dx, .y = point.y + dy };
            if (out.edges.inside(next) and out.edges.at(next) == 0 and out.nms.at(next) >= p.low) {
                out.edges.set(next, 1);
                c.append(c.Point, &queue, next);
            }
        };
    }
    const visited = c.Image.init(width, height);
    var components: std.ArrayList([]const c.Point) = .empty;
    for (0..height) |yy| for (0..width) |xx| {
        const first: c.Point = .{ .x = c.n(xx), .y = c.n(yy) };
        if (out.edges.at(first) == 0 or visited.at(first) != 0) continue;
        var component: std.ArrayList(c.Point) = .empty;
        c.append(c.Point, &component, first);
        visited.set(first, 1);
        head = 0;
        while (head < component.items.len) : (head += 1) {
            const point = component.items[head];
            for (c.offsets) |dy| for (c.offsets) |dx| {
                const next: c.Point = .{ .x = point.x + dx, .y = point.y + dy };
                if (out.edges.inside(next) and out.edges.at(next) != 0 and visited.at(next) == 0) {
                    visited.set(next, 1);
                    c.append(c.Point, &component, next);
                }
            };
        }
        c.append([]const c.Point, &components, component.items);
    };
    out.components = components.items;
    return out;
}
pub fn detect(g: filters.Gradient, p: c.Params) Result {
    var values: std.ArrayList(Corner) = .empty;
    for (0..response.height) |y| for (0..response.width) |x| {
        const point: c.Point = .{ .x = c.n(x), .y = c.n(y) };
        const value = response.at(point);
        if (value < p.harris_threshold) continue;
        var peak = true;
        for (c.offsets) |dy| {
            for (c.offsets) |dx| {
                const other: c.Point = .{ .x = point.x + dx, .y = point.y + dy };
                if ((dx == 0 and dy == 0) or !response.inside(other)) continue;
                const comparison = response.at(other);
                const earlier = other.y < point.y or (other.y == point.y and other.x < point.x);
                if (value < comparison or (value == comparison and earlier)) {
                    peak = false;
                    break;
                }
            }
            if (!peak) break;
        }
        if (peak) c.append(Corner, &values, .{ .point = point, .response = value });
    };
fn paint(overlay: c.Image, point: c.Point) void {
    if (overlay.inside(point)) overlay.set(point, 255);
}
    const input = try c.load(init.io);
    const image = input.image;
    const p = input.params;
    const g = filters.gradient(filters.smooth(image, p));
    const edges = canny.detect(g, p);
    const circle_data = hough.circleVotes(edges.edges, p);
    const circles = c.alloc(Circle, @min(c.u(p.circle_count), circle_data.peaks.len));
    for (circles, 0..) |*circle, index| {
        circle.* = .{ .peak = circle_data.peaks[index] };
    const line_edges: c.Image = .{ .width = image.width, .height = image.height, .data = c.dupe(i64, edges.edges.data) };
    var circle_edge_pixels: i64 = 0;
    for (0..image.height) |y| for (0..image.width) |x| {
        const point: c.Point = .{ .x = c.n(x), .y = c.n(y) };
        if (edges.edges.at(point) == 0) continue;
        for (circles) |circle| if (circumference(point, circle)) {
            line_edges.set(point, 0);
            circle_edge_pixels += 1;
            break;
        };
    };
    const line_data = hough.lineVotes(line_edges, &input.trig, p);
    var lines: std.ArrayList(Line) = .empty;
    var segments: std.ArrayList(Segment) = .empty;
    const claimed = c.Image.init(image.width, image.height);
    const selected = c.alloc(Projected, image.data.len);
    for (line_data.peaks) |peak| {
        if (lines.items.len >= c.u(p.line_count)) break;
        var count: usize = 0;
        for (0..image.height) |y| for (0..image.width) |x| {
            const point: c.Point = .{ .x = c.n(x), .y = c.n(y) };
            if (line_edges.at(point) != 0 and claimed.at(point) == 0 and filters.absolute(hough.rho(point,
                 peak.theta, input.trig, p) - peak.rho) <= p.tolerance) {
                selected[count] = .{ .point = point, .position = point.y * input.trig[c.u(peak.theta)][0] - point.x * input.trig[c.u(peak.theta)][1] };
                count += 1;
            }
        };
        std.mem.sort(Projected, selected[0..count], {}, projectedLess);
        var ids: std.ArrayList(usize) = .empty;
        var begin: usize = 0;
        while (begin < count) {
            var end = begin + 1;
            while (end < count and selected[end].position - selected[end - 1].position <= p.max_gap * 16384) end += 1;
            const start = selected[begin].point;
            const last = selected[end - 1].point;
            const length = chebyshev(start, last) + 1;
            if (length >= p.min_length) {
                c.append(usize, &ids, segments.items.len);
                c.append(Segment, &segments, .{ .start = start, .end = last, .length = length, .pixels = c.n(end - begin),
                     .theta = peak.theta, .line = lines.items.len });
                for (selected[begin..end]) |value| claimed.set(value.point, 1);
            }
            begin = end;
        }
        if (ids.items.len > 0) c.append(Line, &lines, .{ .peak = peak, .segments = ids.items });
    }
    for (3..5) |size| for (0..segments.items.len) |start| {
        var search: Search = .{ .size = size, .start = start, .segments = segments.items, .junctions = junctions.items,
             .adjacency = adjacency, .edges = edges.edges, .params = p, .polygons = &polygon_list };
        search.path[0] = start;
        visit(&search, 1);
    };
    const polygons = polygon_list.items;
    const overlay = c.Image.init(image.width, image.height);
    const edge_image = c.Image.init(image.width, image.height);
    const hough_image = c.Image.init(line_data.votes.width, line_data.votes.height);
    for (image.data, 0..) |value, i| {
        overlay.data[i] = @divFloor(value, p.overlay_divisor);
        edge_image.data[i] = 255 * edges.edges.data[i];
    }
    for (line_data.votes.data, 0..) |value, i| hough_image.data[i] = if (line_data.maximum > 0) @divFloor(255 * value,
         line_data.maximum) else 0;
    for (segments.items) |segment| {
        const points = bresenham(segment.start, segment.end);
        for (points.data[0..points.count]) |point| paint(overlay, point);
    }
    for (circles) |circle| for (circle_data.offsets[c.u(circle.peak.radius - p.r_min)]) |offset| {
        paint(overlay, .{ .x = circle.peak.center.x + offset.x, .y = circle.peak.center.y + offset.y });
    };
    for (corner_data.values) |corner| {
        var e: i64 = -2;
        while (e <= 2) : (e += 1) {
            paint(overlay, .{ .x = corner.point.x + e, .y = corner.point.y });
            paint(overlay, .{ .x = corner.point.x, .y = corner.point.y + e });
        }
    }
    try c.writePgm(init.io, "edges.pgm", edge_image);
    try c.writePgm(init.io, "hough.pgm", hough_image);
    try c.writePgm(init.io, "overlay.pgm", overlay);
        var directions = [_]i64{ 0, 0, 0, 0 };
        for (component) |point| {
            var neighbors: i64 = 0;
            for (c.offsets) |dy| for (c.offsets) |dx| {
                const next: c.Point = .{ .x = point.x + dx, .y = point.y + dy };
                if ((dx != 0 or dy != 0) and image.inside(next) and edges.edges.at(next) != 0) neighbors += 1;
            };
            ends += @intFromBool(neighbors == 1);
    const names = [_][]const u8{ "gradient_nonzero", "gradient_max", "nms_kept", "strong", "weak",
         "edges", "weak_kept", "weak_dropped", "edge_components", "direction_0", "direction_45", "direction_90",
         "direction_135", "circle_candidates", "circle_peaks", "circles", "circle_edge_pixels", "line_edge_pixels",
         "hough_max_votes", "hough_peaks", "lines", "segments", "claimed_pixels", "junctions", "polygons",
         "equilateral_triangle", "right_triangle", "triangle", "square", "rectangle", "parallelogram",
         "trapezoid", "quadrilateral", "corner_candidates", "corners", "corners_on_vertices", "corners_on_segments",
         "corners_unmatched", "vertices_with_corner" };
    var counts = [_]i64{0} ** 39;
    for (image.data, 0..) |_, i| {
        counts[0] += @intFromBool(g.magnitude.data[i] > 0);
        counts[1] = @max(counts[1], g.magnitude.data[i]);
        counts[2] += @intFromBool(edges.nms.data[i] > 0);
        counts[5] += edges.edges.data[i];
        counts[6] += @intFromBool(edges.edges.data[i] != 0 and edges.nms.data[i] >= p.low and edges.nms.data[i] < p.high);
        counts[22] += claimed.data[i];
        if (edges.edges.data[i] != 0) counts[9 + c.u(@divTrunc(edges.direction.data[i], 45))] += 1;
    }
    counts[3] = edges.strong;
    counts[4] = edges.weak;
    counts[7] = edges.weak - counts[6];
    counts[8] = c.n(edges.components.len);
    counts[13] = circle_data.candidates;
    counts[14] = c.n(circle_data.peaks.len);
    counts[15] = c.n(circles.len);
    counts[16] = circle_edge_pixels;
    counts[17] = counts[5] - circle_edge_pixels;
    counts[18] = line_data.maximum;
    counts[19] = c.n(line_data.peaks.len);
    counts[20] = c.n(lines.items.len);
    counts[21] = c.n(segments.items.len);
    counts[23] = c.n(junctions.items.len);
    counts[24] = c.n(polygons.len);
    for (polygons) |polygon| for (25..33) |kind| {
        if (c.eq(polygon.kind, names[kind])) counts[kind] += 1;
    };
    counts[33] = c.n(corner_data.candidates);
    counts[34] = c.n(corner_data.values.len);
    counts[35] = corner_vertices;
    counts[36] = corner_segments;
    counts[37] = c.n(corner_data.values.len) - corner_vertices - corner_segments;
    counts[38] = vertices_with_corner;
    report.add("image {d} {d}", .{ image.width, image.height });
    for (names, counts) |name, count| report.add("{s} {d}", .{ name, count });
    try write(init.io, "lines.txt", line_file);
    try write(init.io, "circles.txt", circle_file);
    try write(init.io, "polygons.txt", polygon_file);
    try write(init.io, "corners.txt", corner_file);
    try write(init.io, "components.txt", component_file);
    try write(init.io, "report.txt", report);
pub fn rho(point: c.Point, theta: i64, trig: *const c.Trig, p: c.Params) i64 {
    return @divFloor(point.x * trig[c.u(theta)][0] + point.y * trig[c.u(theta)][1], 16384 * p.rho_step);
}
